-- gameWE - collector: reference data for an empty database.
--
-- Compiled into the collector (internal/schema): `gamewe db migrate` loads
-- it into a new database, and once into an upgraded older one. Every
-- statement is INSERT IGNORE: it adds only what is missing and never changes
-- existing rows. Change the values afterwards in the web admin or with
-- `gamewe game` / `gamewe option`. These are gameWE's defaults, not copied
-- from any production database:
--   * hlstats_Games    the games your servers run (hlstats_Servers.game)
--   * hlstats_Actions  rewards: reward_player for player actions, reward_team
--                      for every player of the team that wins with this trigger
--   * hlstats_Teams    team codes as they appear in the logs
--   * hlstats_Weapons  skill modifiers (a kill is worth kill_points x modifier
--                      x victim/killer skill). Weapons that are not listed are
--                      added automatically with modifier 1.00.
--   * hlstats_Options  site settings for the web frontend, and the collector's
--                      settings (keys gamewe_*, see CONFIG.md).
-- No admin account is created in hlstats_Users: use the web frontend's
-- `npm run create-admin -- <name>`.
-- Maps are added automatically when a server changes the map.

SET NAMES utf8mb4;

-- Games (rankings). realgame is the base game a ranking belongs to: it picks
-- the log format, the RCON protocol and the in-game replies (see GAMES.md). A
-- ranking cloned from a game (css1 from css) keeps the template's realgame.
INSERT IGNORE INTO hlstats_Games (code, name, realgame, hidden) VALUES
  ('css',        'Counter-Strike: Source', 'css', '0'),
