-- Site settings for the web frontend (not read by the collector).
INSERT IGNORE INTO hlstats_Options (keyname, value) VALUES
  ('sitename', 'gameWE'),
  ('siteurl', ''),
  ('contact', ''),
  ('MinActivity', '28'),          -- days without play before a player leaves the rankings
  ('gamewe_default_game', 'css'), -- game shown first
  ('gamewe_page_size', '50'),     -- rows per page in lists
  -- Collector settings (re-read every 60 s; a missing key uses the same default):
  ('gamewe_start_skill', '1000'),     -- skill of a new player
  ('gamewe_kill_points', '5'),        -- base skill per kill (x victim/killer skill x weapon modifier)
  ('gamewe_headshot_bonus', '0'),     -- extra skill per headshot on top of the 'headshot' action
  ('gamewe_suicide_penalty', '5'),    -- skill lost per suicide
  ('gamewe_teamkill_penalty', '10'),  -- skill lost per teamkill
  ('gamewe_rank_bots', '0'),          -- bots are always recorded; 0 = not ranked, no awards, no effect on skill
  ('gamewe_store_player_ip', '1'),    -- 1 = store IPv4 addresses (personal data, web admin only)
  ('gamewe_store_chat', '1'),         -- 1 = store chat (personal data, web admin only)
  ('gamewe_win_triggers', 'CTs_Win,Terrorists_Win,Target_Bombed,Target_Saved,Bomb_Defused,All_Hostages_Rescued,Hostages_Not_Rescued,VIP_Escaped,VIP_Assassinated,VIP_Not_Escaped,Round_Win'),
  ('gamewe_commands', '1'),           -- 1 = answer !rank, !top10, ... in game
  ('gamewe_menu_time', '15'),         -- seconds the panels (!top10, !rank, ...) stay open
  ('gamewe_rcon_timeout', '5'),       -- seconds for RCON
  ('gamewe_log_lines', '1'),          -- 1 = every received log line in the collector's journal
  ('gamewe_idle_timeout', '300'),     -- seconds without a log line before a player's visit ends; 0 = never
  ('gamewe_command_display', 'panel'), -- !rank, !session, ... as a panel on the left (gameME), chat or both
  ('gamewe_command_prefix', 'gamewe'), -- gameme for servers with the original gameME plugin
  ('gamewe_raw_messages', '0'),       -- 1 = command answers as gamewe_raw_message for a message plugin
  ('gamewe_store_locations', '1'),    -- 1 = kill/death positions in hlstats_Events_Locations
  ('gamewe_geoip_db', '/var/lib/gamewe/GeoLite2-City.mmdb'), -- city database for locations (optional)
  ('gamewe_server_load', '1'),        -- 1 = hlstats_server_load every 10 minutes
  ('gamewe_player_reset', '0'),       -- 1 = players may reset their own stats (!gamewe_reset)
  ('gamewe_player_reset_cooldown', '24'), -- hours between two own resets
  ('gamewe_console_events', '0'),     -- 1 = points of kills and actions in the players' console
  ('gamewe_global_chat', '0'),        -- 1 = player and team actions with points in the chat
  ('gamewe_heartbeat', '0');          -- written by the running collector every 60 s (Unix time)

-- ---------------------------------------------------------------------------
-- Counter-Strike 2 (cs2, Source 2): the CS:GO definitions above (weapons,
-- actions, awards, ranks, ribbons, ribbon classes, teams) for the game cs2,
-- without what CS2 does not have: the VIP actions, the old weapon code galil
-- (CS2 logs galilar) and the CS:GO player models (they came from the
-- SourceMod plugin, which does not run on CS2). Cross-checked against the
-- cs2 rows of HLstatsX:CE (github.com/lovasatt/hlstatsx-community-edition,
-- sql/install.sql, GPL-2.0-or-later).
-- ---------------------------------------------------------------------------
